const __quietstartKits = {
"dailyCheckIn": (// Project-authored business policy. No platform imports, screen reads, input
// execution or daily ledger writes. Targets are opaque refs from one host frame.
function createDailyCheckInKit(options = {}) {
  const dialogs = options.startupDialogs ?? [];
  const totalMs = options.totalMs ?? 45000;
  const phaseMs = options.phaseMs ?? 20000;
  if (!Array.isArray(dialogs) || dialogs.some(d => !d || typeof d.id !== 'string' ||
      !['tree', 'ocr'].includes(d.source)) || !Number.isInteger(totalMs) || totalMs < 1 ||
      !Number.isInteger(phaseMs) || phaseMs < 1) throw Error('invalid-daily-policy');
  const copy = value => JSON.parse(JSON.stringify(value));
  function initial(now) {
    return { phase: 'entry', startedAt: now, phaseAt: now, nextReadAt: 0,
      retries: 0, entryRetries: 0, claimed: false, verifiedToday: false, done: false,
      reason: '', startupVisualChecked: false, verificationReopens: 0, actionSequence: 0 };
  }
  function cadence(s, now) { return !s.done && s.phase !== 'entry' && now - s.phaseAt < 4000 ? 150 : 750; }
  function successful(s) { return s.done && s.claimed &&
    (s.verifiedToday || s.reason === '签到已领取并返回首页'); }
  function valid(s, now) {
    if (!s || !['entry', 'claim', 'claimSent', 'close', 'verify', 'verifyReward'].includes(s.phase) ||
        !Number.isFinite(now) || ['startedAt', 'phaseAt', 'nextReadAt', 'retries', 'entryRetries',
          'verificationReopens', 'actionSequence'].some(k => !Number.isSafeInteger(s[k]) || s[k] < 0) ||
        ['claimed', 'verifiedToday', 'done', 'startupVisualChecked'].some(k => typeof s[k] !== 'boolean')) {
      throw Error('invalid-daily-checkpoint');
    }
  }
  function result(s, outcome = 'waiting', intent, applied) {
    return { status: s.done ? 'complete' : 'running', outcome, checkpoint: s,
      ...(intent ? { intent } : {}), ...(applied ? { applied } : {}) };
  }
  function tap(s, ref, purpose, outcome, applied, optional = false) {
    if (typeof ref !== 'string' || !ref) throw Error('invalid-daily-target');
    return result(s, outcome, { kind: 'tap', targetRef: ref, purpose, optional,
      sequence: s.actionSequence }, applied);
  }
  function dismiss(s, target, purpose) {
    return tap(s, target, purpose, 'dismissed', { stamp: true, delay: 650, startupVisualChecked: false });
  }
  function reopen(s, f) {
    if (s.verificationReopens > 0 || !f.entryTarget) return result(s);
    return tap(s, f.entryTarget, 'reopen-to-verify', 'entry',
      { stamp: true, phase: 'verifyReward', delay: 150, verificationReopensDelta: 1 });
  }
  function decide(checkpoint, observation) {
    const { now, facts: f } = observation ?? {};
    valid(checkpoint, now);
    const s = copy(checkpoint);
    if (s.done) return result(s, 'done');
    if (now < s.nextReadAt) return result(s);
    s.nextReadAt = now + (cadence(s, now) === 150 ? 150 : 650);
    if (now - s.startedAt > totalMs || now - s.phaseAt > phaseMs) {
      s.done = true; s.reason = '签到页面未在观察窗口内完成'; return result(s, 'done');
    }
    // A failed capture or a foreign/ambiguous owner cannot produce a target.
    if (!f || f.ownerValid !== true) return result(s);
    for (const key of ['home', 'dialog', 'completed', 'claimed', 'claimVisible', 'modal', 'canEnter']) {
      if (typeof f[key] !== 'boolean') throw Error('invalid-daily-facts:' + key);
    }
    if (f.completed && f.dialog) {
      s.claimed = true; s.verifiedToday = true; s.done = true; s.reason = '已确认今天签到';
      return f.closeTarget ? tap(s, f.closeTarget, 'close-confirmed', 'success',
        { reason: '已确认今天签到并关闭弹窗' }, true) : result(s, 'success');
    }
    if (s.phase === 'verifyReward') {
      if (now - s.phaseAt > 2500 && f.claimVisible && f.dialog) {
        s.done = true; s.reason = '复查签到页仍显示未领取，未记录当天完成'; return result(s, 'done');
      }
      return result(s);
    }
    if (s.phase === 'entry') {
      // A live claim receiver in the confirmed sign-in dialog is already
      // the requested entry. Do not close and reopen it just to reach claim.
      if (f.dialog && f.claimTarget) return tap(s, f.claimTarget, 'claim', 'claim',
        { stamp: true, phase: 'claimSent', delay: 150 });
      for (const rule of dialogs) {
        const proof = f.startup?.[rule.id];
        if (rule.source !== 'tree' || !proof?.matched) continue;
        return proof.targetRef ? dismiss(s, proof.targetRef, rule.id) : result(s);
      }
      if (f.modal && f.modalDismissTarget) return dismiss(s, f.modalDismissTarget, 'explicit-modal-dismiss');
      if (!s.startupVisualChecked && f.modal && f.home) {
        s.startupVisualChecked = true;
        for (const rule of dialogs) {
          if (rule.source !== 'ocr') continue;
          const proof = f.ocr?.[rule.id];
          if (!proof) {
            // The adapter gathers this declared crop, then calls decide again
            // with the original checkpoint and this same frame's facts.
            return result(copy(checkpoint), 'waiting', { kind: 'read-ocr', ruleRef: rule.id,
              readRegion: rule.readRegion, format: 'jpeg', maxMs: 900 });
          }
          if (proof.failed) { s.startupVisualChecked = false; return result(s); }
          if (!proof.matched) continue;
          return proof.targetRef ? dismiss(s, proof.targetRef, rule.id) : result(s);
        }
      }
      if (f.modal || !f.canEnter) return result(s);
    }
    if (s.phase === 'verify') {
      if (f.home && !f.dialog && !f.claimVisible) {
        s.done = true; s.reason = '签到已领取并返回首页'; return result(s, 'success');
      }
      return result(s);
    }
    if (s.phase === 'close') {
      return f.closeTarget ? tap(s, f.closeTarget, 'close', 'closed',
        { stamp: true, phase: 'verify', delay: 450 }) : reopen(s, f);
    }
    if (s.phase === 'claimSent') {
      if (f.completed || f.claimed) {
        s.claimed = true; s.phase = 'close'; s.phaseAt = now; s.nextReadAt = 0;
        return result(s, 'claimed');
      }
      if (now - s.phaseAt > 1200 && f.home && !f.dialog && !f.claimVisible) return reopen(s, f);
      if (now - s.phaseAt > 6500 && s.retries < 1 && f.claimTarget) {
        s.retries++; s.phase = 'claim'; s.phaseAt = now; s.nextReadAt = 0;
      }
      return result(s);
    }
    if (s.phase === 'claim' && f.claimTarget) return tap(s, f.claimTarget, 'claim', 'claim',
      { stamp: true, phase: 'claimSent', delay: 150 });
    if (s.phase === 'claim') {
      if (now - s.phaseAt >= 1600 && f.home && !f.dialog && !f.claimVisible) {
        if (f.entryTarget && s.entryRetries < 2) return tap(s, f.entryTarget, 'retry-entry', 'entry',
          { stamp: true, delay: 150, entryRetriesDelta: 1 });
        if (s.entryRetries >= 2) { s.done = true; s.reason = '签到入口未打开，本轮停止读取'; return result(s, 'done'); }
      }
      return result(s);
    }
    return f.entryTarget ? tap(s, f.entryTarget, 'entry', 'entry',
      { stamp: true, phase: 'claim', delay: 150 }) : result(s);
  }
  function commit(decision, receipt) {
    if (!decision.intent || decision.intent.kind !== 'tap' || !receipt ||
        !['applied', 'rejected', 'unknown'].includes(receipt.status) ||
        receipt.sequence !== decision.intent.sequence || !Number.isSafeInteger(receipt.at) || receipt.at < 0) {
      throw Error('invalid-daily-receipt');
    }
    const s = copy(decision.checkpoint);
    if (receipt.status !== 'applied') {
      // Closing is optional after definitive completed evidence. An uncertain
      // ordinary input is owned by the host action ledger and must not repeat.
      return decision.intent.optional ? result(s, decision.outcome) :
        { status: 'paused', outcome: 'waiting', reason: 'input-' + receipt.status, checkpoint: s };
    }
    const next = decision.applied;
    if (next.stamp) { s.phaseAt = receipt.at; s.nextReadAt = receipt.at + next.delay; }
    if (next.phase) s.phase = next.phase;
    if (next.reason) s.reason = next.reason;
    if (next.startupVisualChecked !== undefined) s.startupVisualChecked = next.startupVisualChecked;
    s.entryRetries += next.entryRetriesDelta ?? 0;
    s.verificationReopens += next.verificationReopensDelta ?? 0;
    s.actionSequence++;
    return result(s, decision.outcome);
  }
  return { initial, decide, commit, cadence, successful };
})
};
