const __quietstartDailyDismissQueries=["modal-dismiss-0","modal-dismiss-1","modal-dismiss-2","modal-dismiss-3","modal-dismiss-4"];
// The locked, unchanged Kit owns business state. The host owns every query,
// target reference, input receipt and day-completion proof.
const dailyPolicy = __quietstartKits.dailyCheckIn({ startupDialogs: __quietstartDailyDialogs });
const matched = (queries, id) => queries[id]?.matched === true;
const target = (queries, id) => matched(queries, id) ? queries[id]?.targetRef : undefined;

function factsFrom(frame) {
  if (frame?.ownerValid !== true) return { ownerValid: false };
  const q = frame.queries || {};
  const facts = { ownerValid: true, home: matched(q, 'home'), dialog: matched(q, 'dialog'),
    completed: matched(q, 'completed'), claimed: matched(q, 'claimed'),
    claimVisible: matched(q, 'claimVisible'), modal: matched(q, 'modal'),
    canEnter: matched(q, 'canEnter'), entryTarget: target(q, 'entry'),
    claimTarget: target(q, 'claim'), closeTarget: target(q, 'close'), startup: {}, ocr: {} };
  for (const id of __quietstartDailyDismissQueries) {
    const ref = target(q, id);
    if (ref) { facts.modalDismissTarget = ref; break; }
  }
  for (const rule of __quietstartDailyDialogs) {
    if (rule.source === 'tree') facts.startup[rule.id] = {
      matched: matched(q, rule.id + '-context'), targetRef: target(q, rule.id)
    };
  }
  return facts;
}

function message(decision) {
  if (decision.checkpoint.reason) return decision.checkpoint.reason;
  return { entry: '签到入口已打开', claim: '已点击领取，等待确认', claimed: '已确认领取，等待关闭',
    closed: '已关闭签到结果，核对首页', dismissed: '已关闭启动遮挡',
    success: '今日签到已确认' }[decision.outcome] || '正在检查签到页面';
}

function output(checkpoint, now, outcome, completionProof) {
  const successful = dailyPolicy.successful(checkpoint);
  const done = checkpoint.done === true;
  const decision = { checkpoint, outcome };
  if (successful && !completionProof) throw Error('daily-completion-proof-missing');
  return { status: done ? 'complete' : 'waiting', checkpoint: { policy: checkpoint },
    ...(done ? {} : { next: { at: Math.max(now + dailyPolicy.cadence(checkpoint, now),
      checkpoint.nextReadAt, now + 150) } }),
    ...(successful ? { successProof: completionProof } : {}),
    message: message(decision), outcome, successful };
}

export async function onEvent(ctx, event) {
  if (event?.kind !== 'tick' || !Number.isSafeInteger(event.actionSequence) || event.actionSequence < 0) {
    throw Error('invalid-daily-event');
  }
  const now = await ctx.clock.now();
  let before = ctx.checkpoint?.policy;
  if (before == null) {
    before = dailyPolicy.initial(now);
    before.actionSequence = event.actionSequence;
  }
  if (!before.done && now < before.nextReadAt) return output(before, now, 'waiting');
  if (!before.done) {
    const due = dailyPolicy.decide(before, { now, facts: { ownerValid: false } });
    if (due.checkpoint.done) return output(due.checkpoint, now, due.outcome);
  }
  const frame = await ctx.observe.snapshot({ fields: ['queries'], reason: '核对签到声明和当前目标' });
  const facts = factsFrom(frame);
  let decision = dailyPolicy.decide(before, { now, facts });
  let ocrReads = 0;
  while (decision.intent?.kind === 'read-ocr') {
    if (++ocrReads > __quietstartDailyDialogs.length || !__quietstartDailyDialogs.some(rule =>
      rule.id === decision.intent.ruleRef && rule.source === 'ocr')) throw Error('undeclared-daily-ocr');
    facts.ocr[decision.intent.ruleRef] = await ctx.vision.ocr({ ruleRef: decision.intent.ruleRef });
    // The Kit deliberately reevaluates the original checkpoint and the same
    // captured facts after the declared OCR proof has been gathered.
    decision = dailyPolicy.decide(before, { now, facts });
  }
  if (decision.intent?.kind === 'tap') {
    const intent = decision.intent;
    let receipt;
    try {
      receipt = await ctx.actions.perform({ kind: 'tap', targetRef: intent.targetRef,
        idempotencyKey: ctx.run.id + '/' + intent.sequence });
    } catch (error) {
      if (!intent.optional || !frame.completionProof) throw error;
      receipt = { status: 'unknown', at: await ctx.clock.now(), sequence: intent.sequence };
    }
    if (receipt.status === 'not-dispatched') {
      if (intent.optional && frame.completionProof) {
        decision = dailyPolicy.commit(decision, { status: 'rejected',
          sequence: intent.sequence, at: receipt.at });
      } else {
        // No input or durable intent exists. Retry the original Kit state;
        // keep its phase/total deadline and action sequence unchanged.
        const retryAt = await ctx.clock.now();
        const retry = JSON.parse(JSON.stringify(before));
        retry.nextReadAt = Math.max(retry.nextReadAt, retryAt + 150);
        return output(retry, retryAt, 'waiting');
      }
    } else {
      decision = dailyPolicy.commit(decision, { ...receipt,
        status: receipt.status === 'already-applied' ? 'applied' : receipt.status });
    }
  }
  if (decision.status === 'paused') throw Error(decision.reason || 'daily-input-unconfirmed');
  const result = output(decision.checkpoint, await ctx.clock.now(), decision.outcome, frame.completionProof);
  if (decision.outcome !== 'waiting') await ctx.ui.publish({ kind: 'capsule', message: result.message,
    stopped: result.status === 'complete' });
  return result;
}

export function migrate(input) {
  if (input?.from !== 'legacy-daily-checkin/1') throw Error('unsupported-daily-migration');
  const checkpoint = input.checkpoint ?? { policy: null };
  if (!checkpoint || typeof checkpoint !== 'object' || Array.isArray(checkpoint) ||
    Object.keys(checkpoint).some(key => key !== 'policy') ||
    checkpoint.policy !== null && (typeof checkpoint.policy !== 'object' || Array.isArray(checkpoint.policy))) {
    throw Error('invalid-daily-adapter-checkpoint');
  }
  return { schema: 1, checkpoint };
}

